/**
 * diagnosis/location-impact.ts — 办公模式影响分析 (SOG v1.0 新建, P2)
 *
 * 分析远程/混合办公对协作模式的影响。
 * 基于 Location 节点 + BELONGS_TO 连接的人员/团队 + INTERACTS_WITH 边的 channel 属性。
 */

import { SOGNodeType, SOGEdgeType } from '../../sog/sog-core-schema';
import type { DiagnosticModule } from './module-registry';

export interface LocationImpactEntry {
  locationId: string;
  type: 'office' | 'remote' | 'datacenter' | 'factory';
  teams: string[];
  avgCrossLocationInteractions: number;
  channelDistribution: Record<string, number>;
  isolationIndex: number; // 0-1, higher = more isolated
}

export interface LocationImpactReport {
  locations: LocationImpactEntry[];
  overallRemoteHealth: 'healthy' | 'risk_of_silo' | 'insufficient_data';
  interpretation: string;
}

export function computeLocationImpact(
  locations: Array<{
    id: string;
    locationType: 'office' | 'remote' | 'datacenter' | 'factory';
  }>,
  belongsToEdges: Array<{ from: string; to: string; type: SOGEdgeType }>,
  interactions: Array<{
    from: string; to: string;
    channel?: string;
    count: number;
  }>,
  teamPersonIds: string[],
): LocationImpactReport {
  if (locations.length === 0) {
    return {
      locations: [],
      overallRemoteHealth: 'insufficient_data',
      interpretation: '未配置 Location 节点。建议添加办公地点信息以分析远程协作影响。',
    };
  }

  // Map entity → location via BELONGS_TO
  const entityLocation = new Map<string, string>();
  for (const e of belongsToEdges) {
    if (e.type === SOGEdgeType.BELONGS_TO) {
      entityLocation.set(e.from, e.to);
    }
  }

  const locEntries: LocationImpactEntry[] = [];

  for (const loc of locations) {
    const members = teamPersonIds.filter(
      id => entityLocation.get(id) === loc.id,
    );
    const teams = [...new Set(
      belongsToEdges
        .filter(e => e.type === SOGEdgeType.BELONGS_TO && e.to === loc.id)
        .map(e => e.from)
        .filter(id => !teamPersonIds.includes(id)),
    )];

    // Analyze interactions
    let crossLocationCount = 0;
    let sameLocationCount = 0;
    const channelDist: Record<string, number> = {};

    for (const ix of interactions) {
      const fromLoc = entityLocation.get(ix.from);
      const toLoc = entityLocation.get(ix.to);
      const ch = ix.channel || 'unknown';
      channelDist[ch] = (channelDist[ch] || 0) + ix.count;

      if (fromLoc && toLoc && fromLoc !== toLoc) {
        crossLocationCount += ix.count;
      } else {
        sameLocationCount += ix.count;
      }
    }

    const total = crossLocationCount + sameLocationCount;
    const avgCrossLocation = total > 0 ? crossLocationCount / total : 0;

    // Isolation index: public channel interactions across locations are healthy
    const publicChannels = ['public_channel', 'thread', 'topic'];
    const crossPublicCount = interactions
      .filter(ix => {
        const fromLoc = entityLocation.get(ix.from);
        const toLoc = entityLocation.get(ix.to);
        return fromLoc && toLoc && fromLoc !== toLoc &&
          publicChannels.includes(ix.channel || '');
      })
      .reduce((sum, ix) => sum + ix.count, 0);

    const isolationIndex = total > 0
      ? 1 - (crossPublicCount / total)
      : 0;

    locEntries.push({
      locationId: loc.id,
      type: loc.locationType,
      teams,
      avgCrossLocationInteractions: Math.round(avgCrossLocation * 1000) / 1000,
      channelDistribution: channelDist,
      isolationIndex: Math.round(isolationIndex * 1000) / 1000,
    });
  }

  // Overall health
  const remoteLocs = locEntries.filter(l => l.type === 'remote');
  const highIsolation = remoteLocs.filter(l => l.isolationIndex > 0.7);

  let overallRemoteHealth: LocationImpactReport['overallRemoteHealth'] = 'healthy';
  if (remoteLocs.length === 0) {
    overallRemoteHealth = 'healthy';
  } else if (highIsolation.length > remoteLocs.length * 0.5) {
    overallRemoteHealth = 'risk_of_silo';
  }

  return {
    locations: locEntries,
    overallRemoteHealth,
    interpretation: locEntries.length > 0
      ? `${locEntries.length} 个办公地点。${highIsolation.length} 个远程点存在高孤立风险。` +
        (overallRemoteHealth === 'risk_of_silo'
          ? '⚠ 建议增加跨地点公开频道协作。'
          : '远程协作健康。')
      : '数据不足。',
  };
}

export const locationImpactModule: DiagnosticModule = {
  id: 'location-impact',
  version: '1.0.0',
  priority: 'P2',
  requiredDataSources: {},
  confidenceModel: 'statistical',
  label: '办公模式影响',
  description: 'SOG v1.0: Location 节点 + BELONGS_TO + INTERACTS_WITH 分析远程/混合办公对协作的影响',
  ontologyRole: 'analyzer',
  compute: async (_teamId: string) => { return null; },
};
